/***
*
*	Rocket Crowbar 2: rc2.ini, the server's prefs file (cvar rccfgfile).
*
*	Every key is described once in g_rc2Prefs (rc2prefs_table.cpp, generated by
*	scripts/gen_prefs.py from the original's table), and its value lives in the parallel
*	array g_rc2PrefValues, which game code reads directly: RC2Pref(RC2P_Glock_...).f.
*	The loader, writers, the "rccfg" console command and the network sync (rc2prefs.cpp)
*	are the original's functions at 0xaea60-0xb1180.
*
****/

#pragma once

#include "rc2prefs_table.h"

typedef struct edict_s edict_t;

// The record's type word. The names are the original's own, from the "findkey" listing
// (rc2.dll 0xaf890), with the range it prints for each.
enum rc2preftype_e
{
	RC2PT_FLOAT = 0,	  // "FLOAT (-3E38...3E38)"
	RC2PT_SMALLFLOAT = 1, // "SMALL FLOAT (0...655.35)": a float clamped to 0..655.35 on load, sent to clients as a short of hundredths
	RC2PT_DOUBLE = 2,	  // "DOUBLE (-1E308...1E38)"
	RC2PT_INT = 3,		  // "INT (-2E9...2E9)"
	RC2PT_SHORT = 4,	  // "SHORT (-32767...32767)"
	RC2PT_USHORT = 5,	  // "UNSIGNED SHORT (0...65535)": clamped to 0..65535 on load and printed unsigned, but the flag checks read it signed
	RC2PT_BYTE = 6,		  // "BYTE (0...255)"
	RC2PT_BOOL = 7,		  // "BOOL (T/F)": "true", "yes" or a nonzero number is true
};

// The record's flag bits, names as "findkey" prints them. The low ones clamp the value as it
// is parsed (rc2.dll 0xb06a0), in this order: POS_ONLY, THREE_DIGITS, ZERO_TO_ONE,
// NEGATIVE_ONE_TO_ONE, FOUR_DIGITS, GREATER_THEN_ONE, NOT_ZERO.
enum rc2prefflags_e
{
	RC2PF_POS_ONLY = 0x1,			 // below 0 becomes 0
	RC2PF_THREE_DIGITS = 0x2,		 // clamped to 0..999
	RC2PF_NOT_ZERO = 0x4,			 // 0 becomes 1
	RC2PF_GREATER_THEN_ONE = 0x8,	 // below 1 becomes 1
	RC2PF_ZERO_TO_ONE = 0x10,		 // clamped to 0..1
	RC2PF_NEGATIVE_ONE_TO_ONE = 0x20, // clamped to -1..1
	RC2PF_FOUR_DIGITS = 0x40,		 // clamped to 0..9999
	RC2PF_REGISTER_ITEM_INFO = 0x40000000, // a change re-reads the 14 stock weapons' ItemInfo
	RC2PF_NETWORK_SYNC = 0x80000000,	   // sent to clients (user message RCCFG) when it changes
};

// One key, 168 bytes as in the original.
struct rc2pref_t
{
	int iType;			 // rc2preftype_e
	char szHeading[64];	 // [Heading] in rc2.ini
	char szKey[64];
	char szDefault[32];	 // the default, as text
	unsigned int iFlags; // rc2prefflags_e
};

// One value slot, 8 bytes as in the original (orig .bss 0x191bc8).
union rc2prefvalue_t
{
	float f;
	double d;
	int i;
	short s;
	unsigned short us;
	char c;
	unsigned char uc;
	bool b;
};

extern const rc2pref_t g_rc2Prefs[RC2P_COUNT];
extern rc2prefvalue_t g_rc2PrefValues[RC2P_COUNT];

inline rc2prefvalue_t& RC2Pref(rc2pref_e index)
{
	return g_rc2PrefValues[index];
}

// rc2prefs.cpp, names ours
void RC2Prefs_LoadConfig(const char* pszFile);	   // NULL: the rccfgfile cvar; a file in the game dir
void RC2Prefs_SaveConfig(const char* pszFile);	   // every key
void RC2Prefs_SaveDiffConfig(const char* pszFile); // the keys that differ from their defaults (see the dossier)
void RC2Prefs_ResetToDefaults();
void RC2Prefs_SendToClient(edict_t* pClient);	   // the NETWORK_SYNC keys that differ from their defaults
void RC2Prefs_SendResetToClient(edict_t* pClient); // RCCFG 0x7fff: back to defaults
void RC2Prefs_SendToAllClients();
void RC2Prefs_ClientCommand(edict_t* pEntity);	   // the "rccfg" command
